import { Interactive, Sequence, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface PerspectiveMarqueeProps {
  items?: string[];
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  pixelsPerFrame?: number;
  rotateY?: number;
  rotateX?: number;
  perspective?: number;
  fadeColor?: string;
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif";

const DEFAULT_ITEMS = [
  "Vercel",
  "Linear",
  "Stripe",
  "Figma",
  "Notion",
  "Raycast",
  "Arc",
  "Cursor",
];

function PerspectiveMarqueeBase({
  items = DEFAULT_ITEMS,
  fontSize = 84,
  color = "#fafafa",
  fontWeight = 700,
  pixelsPerFrame = 2,
  rotateY = -28,
  rotateX = 8,
  perspective = 1200,
  fadeColor = "#050505",
  speed = 1,
  className,
}: PerspectiveMarqueeProps) {
  const frame = useCurrentFrame() * speed;

  // Approximate width of one full item set so the modulo wraps cleanly.
  const itemPadding = fontSize * 0.9;
  const approxItemWidth = items.reduce(
    (acc, item) => acc + item.length * fontSize * 0.6 + itemPadding,
    0,
  );

  const offset = -((frame * pixelsPerFrame) % approxItemWidth);

  // Render the row 3x so the loop is seamless even when rotated in 3D.
  const rendered = [...items, ...items, ...items];

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        perspective: `${perspective}px`,
      }}
    >
      <div
        style={{
          width: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "flex-start",
          transform: `rotateX(${rotateX}deg) rotateY(${rotateY}deg)`,
          transformStyle: "preserve-3d",
        }}
      >
        <div
          style={{
            display: "flex",
            whiteSpace: "nowrap",
            translate: `${offset}px`,
          }}
        >
          {rendered.map((item, i) => {
            // Approximate this item's center X (relative to the marquee row,
            // including the rolling offset). Used to dial in depth-of-field blur
            // and opacity by horizontal position on screen.
            const itemCenter =
              i * (approxItemWidth / items.length) +
              approxItemWidth / items.length / 2 +
              offset;
            // Normalize roughly to [-1, 1] across a 1280px viewport.
            const norm = (itemCenter - 640) / 640;
            const distance = Math.min(1, Math.abs(norm));
            const blurPx = distance * 6;
            const opacity = 1 - distance * 0.4;

            return (
              <span
                key={i}
                style={{
                  display: "inline-block",
                  fontFamily: FONT_FAMILY,
                  fontSize,
                  fontWeight,
                  color,
                  letterSpacing: "-0.03em",
                  paddingRight: itemPadding,
                  filter: `blur(${blurPx}px)`,
                  opacity,
                }}
              >
                {item}
              </span>
            );
          })}
        </div>
      </div>

      {/* Vignette to fade marquee edges into background */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          background: `linear-gradient(90deg, ${fadeColor} 0%, transparent 18%, transparent 82%, ${fadeColor} 100%)`,
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          background: `linear-gradient(180deg, ${fadeColor} 0%, transparent 25%, transparent 75%, ${fadeColor} 100%)`,
        }}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  fontSize: {
    type: "number",
    min: 24,
    max: 200,
    step: 2,
    default: 84,
    description: "Font size",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#fafafa",
    description: "Color",
  },
  fontWeight: {
    type: "enum",
    default: "700",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  pixelsPerFrame: {
    type: "number",
    min: 0.25,
    max: 10,
    step: 0.25,
    default: 2,
    description: "Pixels / frame",
    hiddenFromList: false,
  },
  rotateY: {
    type: "number",
    min: -60,
    max: 60,
    step: 1,
    default: -28,
    description: "Rotate Y (deg)",
    hiddenFromList: false,
  },
  rotateX: {
    type: "number",
    min: -30,
    max: 30,
    step: 1,
    default: 8,
    description: "Rotate X (deg)",
    hiddenFromList: false,
  },
  perspective: {
    type: "number",
    min: 400,
    max: 3000,
    step: 50,
    default: 1200,
    description: "Perspective",
    hiddenFromList: false,
  },
  fadeColor: {
    type: "color",
    default: "#050505",
    description: "Fade color",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["fontSize","color","fontWeight","pixelsPerFrame","rotateY","rotateX","perspective","fadeColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  fontSize: 84,
  color: "#fafafa",
  fontWeight: "700",
  pixelsPerFrame: 2,
  rotateY: -28,
  rotateX: 8,
  perspective: 1200,
  fadeColor: "#050505",
  speed: 1,
};

type PerspectiveMarqueeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PerspectiveMarqueeBase>;

const PerspectiveMarqueeInner = forwardRef<
  HTMLDivElement,
  PerspectiveMarqueeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PerspectiveMarquee>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PerspectiveMarqueeBase
          {...(componentProps as unknown as ComponentProps<typeof PerspectiveMarqueeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PerspectiveMarquee = Interactive.withSchema({
  Component: PerspectiveMarqueeInner,
  componentName: "<PerspectiveMarquee>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
